head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.fn_GetPar = undefined, scwin.fn_SetPar = undefined, scwin.strCdSch = "";
scwin.vScrenID = "ULDSTF92018.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var strDepCd = "";
    var arrPar = new Array();
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar);
        strDepCd = (arrPar.length >= 1 ? arrPar[0] : "");
        scwin.strCdSch = (arrPar.length >= 2 ? arrPar[1] : ""); // 조회 후 위치할 사원번호

    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listEmpCd&inputMessageId=KRX_EMP_INOUT&outputMessageId=KRX_EMP_INOUT";
    url += "&DEP_CD=" + strDepCd;
    url += "&EMP_NM=" + txb_Search.getValue();
    dts.DataID = encodeURI(url);
    dts.reset();
};
scwin.dts_OnLoadError = function() {
    $c.stf.alert_error(dts);
};
scwin.dts_OnLoadCompleted = function(rowcount) {
    if (dts.errorMsg) {
        $c.win.alert(dts.errorMsg);
    } else {
        txb_TotCnt.setValue("총 " + rowcount + " 건");

        // 초기1회 초기값으로 설정된 회사코드를 검색한다.
        if (scwin.strCdSch != "") {
            for (var i = 1; i <= dts.getTotalRow(); i++) {
                if (scwin.strCdSch == dts.getCellData(i, 1)) {
                    dts.setRowPosition(i, 0);
                    break;
                }
            }
            scwin.strCdSch = "";
        }
    }
};
scwin.grd_OnDblClick = async function(row, colid) {
    var arrPar = new Array();
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = {
            EMP_NO: dts.getCellData(dts.getRowPosition(), "EMP_NO"),
            EMP_NM: dts.getCellData(dts.getRowPosition(), "EMP_NM"),
            DEP_CD: dts.getCellData(dts.getRowPosition(), "DEP_CD"),
            DEP_NM: dts.getCellData(dts.getRowPosition(), "DEP_NM")
        };
        scwin.fn_SetPar(arrPar);
    }
    await $c.frame.CloseFrame();
};
scwin.img_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    window.document.body.scroll = "no";
    var arrPar = new Array();
    /***************************************
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
    ***************************************/
    var parentWin = $c.frame.path("../");
    if (parentWin != undefined) {
        scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
        scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
    }
    scwin.fn_list_sync();
};
